'use strict';
const $=id=>document.getElementById(id);
const PAGES={dashboard:'Dashboard',repairs:'Reparaties',customers:'Klanten',refurb:'Refurbished voorraad',sales:'Verkopen',parts:'Onderdelen / voorraad',payments:'Betalingen',invoices:'Facturen',accounting:'Boekhouding',reports:'Rapporten',warranty:'Garantie',employees:'Medewerkers',audit:'Auditlog',settings:'Instellingen'};
const STATUS=['Binnengebracht','Diagnose','Wachten op klant','Wachten op onderdeel','In reparatie','Kwaliteitscontrole','Klaar','Afgehaald','Geannuleerd'];
const TRANSITIONS={
 'Binnengebracht':['Diagnose','Geannuleerd'],
 'Diagnose':['Wachten op klant','Wachten op onderdeel','In reparatie','Geannuleerd'],
 'Wachten op klant':['Diagnose','Wachten op onderdeel','In reparatie','Geannuleerd'],
 'Wachten op onderdeel':['Diagnose','In reparatie','Geannuleerd'],
 'In reparatie':['Diagnose','Kwaliteitscontrole','Geannuleerd'],
 'Kwaliteitscontrole':['In reparatie','Klaar'],
 'Klaar':['In reparatie','Afgehaald'],
 'Afgehaald':[],
 'Geannuleerd':['Binnengebracht']
};
const STATUS_META={
 'Binnengebracht':{label:'Binnengebracht',desc:'Toestel is ingeboekt en wacht op diagnose.'},
 'Diagnose':{label:'Diagnose',desc:'Technicus onderzoekt het toestel en bepaalt de herstelopties.'},
 'Wachten op klant':{label:'Wachten op akkoord',desc:'Offerte of beslissing ligt bij de klant.'},
 'Wachten op onderdeel':{label:'Onderdeel besteld',desc:'Een noodzakelijk onderdeel is besteld of nog niet beschikbaar.'},
 'In reparatie':{label:'In reparatie',desc:'Het toestel wordt momenteel hersteld.'},
 'Kwaliteitscontrole':{label:'Kwaliteitscontrole',desc:'De reparatie is uitgevoerd en het toestel wordt getest.'},
 'Klaar':{label:'Klaar voor afhaling',desc:'Het toestel is klaar en kan na betaling worden afgehaald.'},
 'Afgehaald':{label:'Afgerond & opgehaald',desc:'Het toestel is afgehaald en de garantie is gestart.'},
 'Geannuleerd':{label:'Geannuleerd',desc:'Dit reparatiedossier is geannuleerd.'}
};
const QC=['Visuele controle','Scherm & touch','Laden / batterij','Camera','Microfoon & speakers','Wi‑Fi / Bluetooth','Biometrie indien aanwezig','Eindtest zonder foutmelding'];
const DEFAULT_INVENTORY={};
const now=()=>new Date().toLocaleString('nl-BE',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
const uid=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>'€ '+(+n||0).toFixed(2).replace('.',',');
const seed=()=>({});
function auditEvent(actor,action,oldValue='',newValue='',source='medewerker'){return{id:uid('AUD'),at:now(),actor,action,oldValue:String(oldValue??''),newValue:String(newValue??''),source};}
function mk(x={}){const base={name:'',phone:'',email:'',deviceType:'Smartphone',device:'Onbekend toestel',serial:'Niet opgegeven',trackHash:uid('trk'),customerStatementOriginal:'',customerAddenda:[],damage:'',accessories:'',tech:'',unlock:'',status:'Binnengebracht',priority:'Normaal',technician:'Niet toegewezen',location:'',dueDate:'',diagnosis:'',tests:'',outcome:'Herstelbaar',parts:[],laborHours:0,laborRate:70,otherCost:0,quotes:[],payments:[],photos:0,photoConfirmed:false,qc:{},qcComplete:false,warranty:false,documents:['Intakebewijs'],communications:[],audit:[]};const r=Object.assign(base,x);if(!r.audit.length)r.audit=[auditEvent('systeem','Dossier aangemaakt','',r.status,'systeem')];return r;}
function migrate(r){const old=r||{},n=mk(Object.assign({},old));if(!n.customerStatementOriginal)n.customerStatementOriginal=old.problem||'';if(!n.trackHash)n.trackHash=uid('trk');if(!n.deviceType)n.deviceType='Smartphone';if(!Array.isArray(n.customerAddenda))n.customerAddenda=[];if(!Array.isArray(n.parts))n.parts=[];if(!Array.isArray(n.quotes)){n.quotes=[];if(old.quote)n.quotes.push({id:uid('Q'),version:1,amount:+old.quote||0,note:old.quoteNote||'',status:old.q==='approved'?'approved':old.q==='rejected'?'rejected':'open',createdAt:now()});}if(!Array.isArray(n.payments)){n.payments=[];if(old.deposit)n.payments.push({id:uid('PAY'),ref:'LEGACY-DEPOSIT',amount:+old.deposit,method:'Onbekend',type:'Voorschot',at:now(),status:'confirmed'});if(old.paid)n.payments.push({id:uid('PAY'),ref:old.paymentRef||'LEGACY-PAY',amount:+old.paid,method:old.paymentMethod||'Onbekend',type:'Betaling',at:now(),status:'confirmed'});}if(!Array.isArray(n.audit))n.audit=[];if(!Array.isArray(n.documents))n.documents=['Intakebewijs'];if(!n.qc||Array.isArray(n.qc))n.qc={};return n;}
let repairs;try{repairs=JSON.parse(localStorage.getItem('rf07v3'))||JSON.parse(localStorage.getItem('rf07v2'))||seed();}catch(e){repairs=seed();}
Object.keys(repairs).forEach(k=>repairs[k]=migrate(repairs[k]));
let inventory;try{inventory=JSON.parse(localStorage.getItem('rfInventoryV3'))||structuredClone(DEFAULT_INVENTORY);}catch(e){inventory=JSON.parse(JSON.stringify(DEFAULT_INVENTORY));}
/* Shared POS stock for repair parts. Legacy inventory is retained only for older dossiers. */
const RF_SHARED_PRODUCTS='rfPosProductsV1',RF_SHARED_MOVEMENTS='rfPosStockMovementsV1';
function rfReadShared(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
function rfSharedProducts(){const p=rfReadShared(RF_SHARED_PRODUCTS,[]);return Array.isArray(p)?p:[]}
function rfStockChange(productId,delta,reason,reference){
 const oldProducts=localStorage.getItem(RF_SHARED_PRODUCTS),oldMovements=localStorage.getItem(RF_SHARED_MOVEMENTS);
 const products=rfSharedProducts(),p=products.find(x=>x.id===productId&&x.active!==false);
 if(!p||!Number.isInteger(delta)||!Number.isInteger(p.stock)||p.stock+delta<0)return false;
 p.stock+=delta;
 const movement={id:uid('MOV'),at:new Date().toISOString(),productId:p.id,productName:p.name,delta,balance:p.stock,reason,reference};
 try{
  const movements=rfReadShared(RF_SHARED_MOVEMENTS,[]);
  localStorage.setItem(RF_SHARED_MOVEMENTS,JSON.stringify([...movements,movement]));
  localStorage.setItem(RF_SHARED_PRODUCTS,JSON.stringify(products));
  return true;
 }catch(e){
  try{if(oldProducts===null)localStorage.removeItem(RF_SHARED_PRODUCTS);else localStorage.setItem(RF_SHARED_PRODUCTS,oldProducts);
  if(oldMovements===null)localStorage.removeItem(RF_SHARED_MOVEMENTS);else localStorage.setItem(RF_SHARED_MOVEMENTS,oldMovements)}catch{}
  return false;
 }
}
let selected='',activeRepairTab='overview',repairView='board';
let next=Math.max(0,...Object.keys(repairs).map(k=>Number(k.split('-').pop())||0));
function save(){localStorage.setItem('rf07v3',JSON.stringify(repairs));localStorage.setItem('rfInventoryV3',JSON.stringify(inventory));}
function log(r,action,oldValue='',newValue='',actor='Medewerker',source='medewerker'){r.audit.unshift(auditEvent(actor,action,oldValue,newValue,source));}
function currentQuote(r){return r.quotes.slice().sort((a,b)=>b.version-a.version)[0]||null;}
function paidTotal(r){return r.payments.filter(p=>p.status==='confirmed').reduce((s,p)=>s+(+p.amount||0),0);}
function quoteAmount(r){const q=currentQuote(r);return q?+q.amount||0:0;}
function due(r){return Math.max(0,quoteAmount(r)-paidTotal(r));}
function calc(r){const parts=r.parts.reduce((s,p)=>s+(+p.price||0)*(+p.qty||1),0),labor=(+r.laborHours||0)*(+r.laborRate||0),other=+r.otherCost||0;return{parts,labor,other,total:parts+labor+other};}
function toast(m){const t=$('toast');if(!t)return;t.textContent=m;t.classList.add('on');setTimeout(()=>t.classList.remove('on'),2300);}
function overlay(t,h){$('ot').textContent=t;$('oc').innerHTML=h;$('overlay').classList.remove('hidden');}
function closeOverlay(){$('overlay').classList.add('hidden');}
function go(id){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$(id)?.classList.add('active');document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===id));$('title').textContent=PAGES[id]||id;if(id==='repairs')renderRepairList();window.scrollTo(0,0);}
function setStatus(r,newStatus,reason=''){const old=r.status;if(old===newStatus)return true;if(!(TRANSITIONS[old]||[]).includes(newStatus)){toast('Status '+old+' → '+newStatus+' is niet toegestaan.');return false;}r.status=newStatus;log(r,'Status gewijzigd',old,newStatus);if(reason)log(r,'Reden statuswijziging','',reason);return true;}
function repairShell(){const sec=$('repairs');if(!sec)return;sec.innerHTML=`<div class="grid4"><div class="card metric">Actief<b id="rpActive">0</b><span class="kpi-note">lopende dossiers</span></div><div class="card metric">Wacht op akkoord<b id="rpWait">0</b></div><div class="card metric">Werkbank / QC<b id="rpBench">0</b></div><div class="card metric">Klaar<b id="rpReady">0</b></div></div><div class="card" style="margin-top:12px"><div class="row space wrap"><div><h3 style="margin:0">Reparaties</h3><div class="muted">Van ontvangst tot afhaling, stap voor stap.</div></div><div class="toolbar"><button class="btn s" data-action="repair-view" data-view="board">Kaarten</button><button class="btn s" data-action="repair-view" data-view="table">Tabel</button><button class="btn g" data-action="repair-new">+ Nieuwe intake</button></div></div><div class="grid2" style="margin-top:12px"><div class="field"><label>Zoeken</label><input id="repairSearch" placeholder="Ticket, klant, toestel, IMEI/serial, bakje..."></div><div class="field"><label>Status</label><select id="repairFilter"><option value="">Alle statussen</option>${STATUS.map(s=>`<option>${s}</option>`).join('')}</select></div></div></div><div id="repairWorkspace" style="margin-top:12px"></div>`;}
function filteredRepairs(){const q=($('repairSearch')?.value||'').toLowerCase(),f=$('repairFilter')?.value||'';return Object.entries(repairs).filter(([t,r])=>{const hay=[t,r.name,r.phone,r.email,r.device,r.serial,r.location,r.customerStatementOriginal].join(' ').toLowerCase();return(!q||hay.includes(q))&&(!f||r.status===f)}).sort((a,b)=>b[0].localeCompare(a[0]));}
function updateRepairStats(){let active=0,wait=0,bench=0,ready=0;Object.values(repairs).forEach(r=>{if(!['Afgehaald','Geannuleerd'].includes(r.status))active++;if(r.status==='Wachten op klant')wait++;if(['In reparatie','Kwaliteitscontrole','Wachten op onderdeel','Diagnose'].includes(r.status))bench++;if(r.status==='Klaar')ready++;});$('rpActive').textContent=active;$('rpWait').textContent=wait;$('rpBench').textContent=bench;$('rpReady').textContent=ready;}
function statusBadge(r){return `<span class="badge">${esc(STATUS_META[r.status]?.label||r.status)}</span>`;}
function renderRepairList(){if(!$('repairWorkspace'))repairShell();updateRepairStats();const rows=filteredRepairs();if(repairView==='table'){renderRepairTable(rows);return;}const selectedExists=repairs[selected];if(!selectedExists&&rows[0])selected=rows[0][0];$('repairWorkspace').innerHTML=`<div style="display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,1fr);gap:12px" class="repair-v3-grid"><div><div class="row space" style="margin-bottom:8px"><b>Lopende herstellingen</b><span class="small muted">Klik een ticket voor snelbeheer</span></div><div id="repairCards">${rows.map(([t,r])=>repairCard(t,r)).join('')||'<div class="card muted">Geen reparaties gevonden.</div>'}</div></div><div id="quickPanel"></div></div>`;renderQuickPanel();}
function repairCard(t,r){const q=currentQuote(r),sel=t===selected;return `<div class="card" data-action="repair-select" data-ticket="${esc(t)}" style="margin-bottom:10px;cursor:pointer;border-color:${sel?'#6ea8fe':'var(--l)'}"><div class="row space wrap"><div><div class="row wrap"><span class="ticket">${esc(t)}</span><span class="badge">${esc(r.location||'Geen locatie')}</span><span class="badge">${esc(r.priority)}</span></div><h3 style="margin:7px 0 3px">${esc(r.device)}</h3><div class="small muted">${esc(r.name)} · ${esc(r.phone||'geen telefoon')}</div></div><div style="text-align:right">${statusBadge(r)}<div class="small muted" style="margin-top:5px">${esc(r.dueDate||'geen datum')}</div></div></div><div class="row space" style="margin-top:12px;padding-top:10px;border-top:1px solid var(--l)"><span class="small" style="max-width:70%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(r.customerStatementOriginal)}</span><b>${q?euro(q.amount):'Nog geen offerte'}</b></div></div>`;}
function renderRepairTable(rows){$('repairWorkspace').innerHTML=`<div class="card"><div class="table"><table><thead><tr><th>Ticket</th><th>Klant</th><th>Toestel</th><th>Locatie</th><th>Status</th><th>Offerte</th><th>Saldo</th><th></th></tr></thead><tbody>${rows.map(([t,r])=>`<tr><td class="ticket">${esc(t)}</td><td>${esc(r.name)}<br><span class="small muted">${esc(r.phone)}</span></td><td>${esc(r.device)}<br><span class="small muted">${esc(r.serial)}</span></td><td>${esc(r.location||'—')}</td><td>${statusBadge(r)}</td><td>${quoteAmount(r)?euro(quoteAmount(r)):'—'}</td><td>${euro(due(r))}</td><td><button class="btn s" data-action="repair-select" data-ticket="${esc(t)}">Open</button></td></tr>`).join('')||'<tr><td colspan="8">Geen reparaties.</td></tr>'}</tbody></table></div></div><div id="quickPanel" style="margin-top:12px"></div>`;renderQuickPanel();}
function renderQuickPanel(){const panel=$('quickPanel');if(!panel)return;const r=repairs[selected];if(!r){panel.innerHTML='<div class="card muted">Selecteer een reparatie.</div>';return;}const q=currentQuote(r);panel.innerHTML=`<div class="card" style="position:sticky;top:20px"><div class="row space"><div><div class="small muted">${esc(selected)}</div><h2 style="margin:3px 0">${esc(r.device)}</h2></div>${statusBadge(r)}</div><div class="grid2" style="margin-top:10px"><div class="demo-card"><span class="small muted">Opslaglocatie</span><br><b>${esc(r.location||'—')}</b></div><div class="demo-card"><span class="small muted">Toegangscode</span><br><b>${r.unlock?'••••':'Geen'}</b></div></div><div class="demo-card" style="margin-top:10px"><b>${esc(r.name)}</b><br><span class="small muted">${esc(r.phone||'—')} · ${esc(r.email||'—')}</span></div><div class="demo-card" style="margin-top:10px"><span class="small muted">Prijsopgave</span><h3 style="margin:4px 0">${q?euro(q.amount):'Nog geen offerte'}</h3><span class="small">${q?esc(q.status):'Maak eerst een diagnose/offerte.'}</span></div><div class="toolbar" style="margin-top:12px"><button class="btn g" data-action="repair-open-full" data-ticket="${esc(selected)}">📂 Open reparatiedossier</button><button class="btn s" data-action="track" data-ticket="${esc(selected)}">Klantstatus bekijken</button></div><div class="toolbar" style="margin-top:8px"><button class="btn s" data-action="print-preview" data-mode="sticker" data-ticket="${esc(selected)}">Toestellabel afdrukken</button><button class="btn s" data-action="print-preview" data-mode="receipt" data-ticket="${esc(selected)}">Ontvangstbewijs afdrukken</button></div><div class="small muted" style="margin-top:12px">Volgende actie: ${esc(nextAction(r))}</div></div>`;}
function progress(r){const stages=['Ontvangst','Diagnose','Offerte','Herstelling','Afhaling'];const x=r.status;const n=x==='Binnengebracht'?0:x==='Diagnose'?1:['Wachten op klant','Wachten op onderdeel'].includes(x)?2:['In reparatie','Kwaliteitscontrole'].includes(x)?3:4;return '<div class="rf-repair-journey">'+stages.map((v,i)=>'<span class="'+(i===n?'current':i<n?'complete':'')+'">'+(i<n?'✓ ':i+1+'. ')+v+'</span>').join('')+'</div>';}
const TABS=[['intake','Ontvangst'],['diagnosis','Diagnose'],['quote','Offerte'],['qc','Herstelling'],['payment','Afhaling']];
function workflowTab(r){const s=r.status;return s==='Binnengebracht'?'intake':s==='Diagnose'?'diagnosis':['Wachten op klant','Wachten op onderdeel'].includes(s)?'quote':['In reparatie','Kwaliteitscontrole'].includes(s)?'qc':'payment';}
function nextAction(r){if(r.status==='Binnengebracht')return'Diagnose starten.';if(r.status==='Diagnose')return'Diagnose afronden en offerte maken.';if(r.status==='Wachten op klant')return'Wachten op klantbeslissing.';if(r.status==='Wachten op onderdeel')return'Onderdeel ontvangen/reserveren.';if(r.status==='In reparatie')return'Reparatie uitvoeren en naar kwaliteitscontrole.';if(r.status==='Kwaliteitscontrole')return'QC volledig uitvoeren.';if(r.status==='Klaar')return due(r)>0?'Open saldo ontvangen.':'Toestel afgeven.';if(r.status==='Afgehaald')return'Garantie actief.';return'Dossier geannuleerd.';}
function detail(ticket,tab){selected=ticket;go('repairs');const r=repairs[ticket];if(!r)return;activeRepairTab=tab||workflowTab(r);if(activeRepairTab==='parts')activeRepairTab='quote';if(activeRepairTab==='photos')activeRepairTab='intake';const c=calc(r);$('repairWorkspace').innerHTML=`<div class="card"><div class="row space wrap"><div><button class="btn s" data-action="repair-back">← Terug naar overzicht</button><div class="small muted" style="margin-top:10px">${esc(ticket)}</div><h2 style="margin:3px 0">${esc(r.device)}</h2><div>${esc(r.name)} · ${esc(r.phone||'geen telefoon')} · ${esc(r.serial)}</div></div><div class="toolbar"><span class="badge">${esc(r.priority)}</span>${statusBadge(r)}<button class="btn s" data-action="track" data-ticket="${esc(ticket)}">Track & Trace</button><button class="btn s" data-action="print-preview" data-mode="sticker" data-ticket="${esc(ticket)}">Print</button></div></div>${progress(r)}<div class="rf-repair-nav">${TABS.map(([id,l])=>`<button class="btn ${activeRepairTab===id?'g':'s'}" data-action="repair-tab" data-tab="${id}" data-ticket="${esc(ticket)}">${l}</button>`).join('')}</div><div id="repairTabContent">${tabContent(ticket,r,c)}</div><details class="rf-repair-more"><summary>Meer dossieropties</summary><div class="toolbar"><button class="btn s" data-action="repair-tab" data-tab="overview" data-ticket="${esc(ticket)}">Overzicht</button><button class="btn s" data-action="repair-tab" data-tab="documents" data-ticket="${esc(ticket)}">Documenten</button><button class="btn s" data-action="repair-tab" data-tab="timeline" data-ticket="${esc(ticket)}">Historiek</button></div></details></div>`;}
function intakePhotos(ticket,r){const imgs=Array.isArray(r.photoImages)?r.photoImages:[];return `<div class="rf-photo-grid">${imgs.map((img,i)=>`<div class="rf-photo-item"><img src="${esc(img.data)}" alt="Ontvangstfoto ${i+1}"><span>Foto ${i+1}</span></div>`).join('')}${imgs.length===0?'<p class="muted">Nog geen foto toegevoegd.</p>':''}</div><label class="btn s rf-photo-upload" for="rfPhotoFile">📷 Foto toevoegen</label><input id="rfPhotoFile" type="file" accept="image/*" capture="environment" style="position:absolute;width:1px;height:1px;opacity:0" ${imgs.length>=4?'disabled':''}><p class="small muted">Maximaal 4 gecomprimeerde foto's. Opgeslagen in deze browser, niet in de cloud.</p>`;}
function quoteParts(ticket,r){return `<div class="row space wrap"><div><h3>Onderdelen</h3><div class="muted">Onderdelen voor de prijsopgave.</div></div><button class="btn g" data-action="repair-add-part" data-ticket="${esc(ticket)}">+ Onderdeel</button></div><div class="table"><table><tr><th>Onderdeel</th><th>Aantal</th><th>Kost</th><th>Verkoop</th><th>Status</th><th></th></tr>${r.parts.map((p,i)=>`<tr><td>${esc(p.name)}</td><td>${p.qty}</td><td>${euro(p.cost)}</td><td>${euro(p.price)}</td><td><select data-action="repair-part-status" data-ticket="${esc(ticket)}" data-index="${i}">${['reserved','ordered','received','used'].map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></td><td><button class="btn r" data-action="repair-remove-part" data-index="${i}" data-ticket="${esc(ticket)}">Verwijder</button></td></tr>`).join('')||'<tr><td colspan="6">Nog geen onderdelen.</td></tr>'}</table></div><div class="demo-card" style="margin-top:10px"><b>Beschikbare voorraad:</b> ${rfSharedProducts().filter(p=>p.active!==false).map(p=>`${esc(p.name)}: ${p.stock}`).join(' · ')}</div>`;}
function tabContent(ticket,r,c){const q=currentQuote(r);if(activeRepairTab==='overview')return `<div class="grid2"><div class="demo-card"><h3>Klant & toestel</h3><p><b>${esc(r.name)}</b><br>${esc(r.phone||'—')} · ${esc(r.email||'—')}</p><p>${esc(r.deviceType)} · ${esc(r.device)}<br>${esc(r.serial)}</p><p>Technicus: <b>${esc(r.technician)}</b><br>Locatie: <b>${esc(r.location||'—')}</b><br>Verwacht klaar: <b>${esc(r.dueDate||'—')}</b></p></div><div class="demo-card"><h3>Volgende actie</h3><p>${esc(nextAction(r))}</p>${overviewActions(ticket,r)}</div><div class="demo-card"><h3>Originele klantverklaring 🔒</h3><p>${esc(r.customerStatementOriginal||'Geen beschrijving.')}</p>${r.customerAddenda.map(a=>`<p class="small"><b>Addendum ${esc(a.at)}:</b> ${esc(a.text)}</p>`).join('')}</div><div class="demo-card"><h3>Financieel</h3><p>Onderdelen ${euro(c.parts)} · arbeid ${euro(c.labor)} · overige ${euro(c.other)}</p><h3>${q?`Offerte v${q.version}: ${euro(q.amount)}`:'Nog geen offerte'}</h3><p>Betaald ${euro(paidTotal(r))} · open ${euro(due(r))}</p></div></div>`;
if(activeRepairTab==='intake')return (`<div class="grid2"><div><div class="demo-card"><h3>Originele klantverklaring 🔒</h3><p>${esc(r.customerStatementOriginal)}</p></div><div class="field"><label>Addendum/correctie</label><textarea id="riAddendum" placeholder="Nieuwe informatie of correctie..."></textarea><button class="btn s" data-action="repair-add-addendum" data-ticket="${esc(ticket)}">Addendum toevoegen</button><label>Zichtbare schade</label><textarea id="riDamage">${esc(r.damage)}</textarea><label>Accessoires</label><input id="riAccessories" value="${esc(r.accessories)}"></div></div><div class="field"><label>Technicusnotitie intake</label><textarea id="riTech">${esc(r.tech)}</textarea><label>Prioriteit</label><select id="riPriority">${['Laag','Normaal','Hoog','Spoed'].map(x=>`<option ${x===r.priority?'selected':''}>${x}</option>`).join('')}</select><label>Technicus</label><input id="riTechnician" value="${esc(r.technician)}"><label>Locatie / baknummer</label><input id="riLocation" value="${esc(r.location)}"><label>Verwachte klaar-datum</label><input id="riDue" type="date" value="${esc(r.dueDate)}"><label>Toestelcode / PIN</label><div class="row"><input id="riUnlock" type="password" value="${esc(r.unlock)}"><button class="btn s" data-action="repair-toggle-unlock" data-ticket="${esc(ticket)}">Tonen</button></div><button class="btn g" data-action="repair-save-intake" data-ticket="${esc(ticket)}">Intakevelden opslaan</button></div></div>`)+`<div class="rf-stage-section"><h3>Foto's bij ontvangst</h3><p>Leg de toestand van het toestel vast voordat je begint.</p>${intakePhotos(ticket,r)}</div><div class="rf-stage-next"><button class="btn g" data-action="repair-tab" data-tab="diagnosis" data-ticket="${esc(ticket)}">Verder naar diagnose →</button></div>`;
if(activeRepairTab==='diagnosis')return `<div class="rf-guided-heading"><span>STAP 2 VAN 5</span><h3>Onderzoek het toestel</h3><p>Schrijf op wat je hebt vastgesteld. Je kunt de diagnose later aanpassen.</p></div><div class="grid2"><div class="field"><label>Wat is er defect?</label><textarea id="rdDiagnosis" placeholder="Bijv. laadconnector beschadigd">${esc(r.diagnosis)}</textarea><label>Wat heb je getest?</label><textarea id="rdTests">${esc(r.tests)}</textarea></div><div class="field"><label>Uitkomst</label><select id="rdOutcome">${['Herstelbaar','Niet herstelbaar','Meer onderzoek nodig','Data recovery risico'].map(x=>`<option ${x===r.outcome?'selected':''}>${x}</option>`).join('')}</select><label>Geschatte werkuren</label><input id="rdHours" type="number" min="0" step="0.25" value="${r.laborHours}"><label>Uurtarief (€)</label><input id="rdRate" type="number" min="0" step="0.01" value="${r.laborRate}"><button class="btn g" data-action="repair-save-diagnosis" data-ticket="${esc(ticket)}">Diagnose bewaren</button></div></div><div class="rf-guided-next"><p>Na de diagnose maak je de offerte op met onderdelen en werkuren.</p>${r.diagnosis?`<button class="btn s" data-action="repair-tab" data-tab="quote" data-ticket="${esc(ticket)}">Offerte voorbereiden →</button>`:'<span class="small muted">Bewaar eerst de diagnose.</span>'}</div>`;
if(activeRepairTab==='quote')return `<div class="rf-stage-section"><h3>Onderdelen voor deze offerte</h3>${quoteParts(ticket,r)}</div>`+(`<div class="grid2"><div class="demo-card"><h3>Prijsberekening</h3><p>Onderdelen: ${euro(c.parts)}<br>Arbeid: ${euro(c.labor)}<br>Overige: ${euro(c.other)}</p><h2>Berekend: ${euro(c.total)}</h2></div><div class="field"><label>Offertebedrag</label><input id="rqAmount" type="number" min="0" step="0.01" value="${q?+q.amount:c.total}"><label>Overige kosten</label><input id="rqOther" type="number" min="0" step="0.01" value="${r.otherCost}"><label>Omschrijving voor klant</label><textarea id="rqNote">${esc(q?.note||'')}</textarea><button class="btn g" data-action="repair-save-quote" data-ticket="${esc(ticket)}">Offerte opslaan</button></div></div><div class="card" style="margin-top:12px"><h3>Versiehistoriek</h3>${r.quotes.slice().reverse().map(v=>`<div class="demo-card" style="margin:8px 0"><b>v${v.version} · ${euro(v.amount)}</b> · ${esc(v.status)}<br><span class="small muted">${esc(v.createdAt)} ${v.approvedAt?'· goedgekeurd '+esc(v.approvedAt):''}</span><p>${esc(v.note)}</p></div>`).join('')||'<p>Nog geen offerte.</p>'}</div>`)+`<div class="rf-stage-next">${q?.status==='approved'?`<button class="btn g" data-action="repair-tab" data-tab="qc" data-ticket="${esc(ticket)}">Verder naar herstelling →</button>`:'<span class="small muted">Wacht eerst op het akkoord van de klant.</span>'}</div>`;
if(activeRepairTab==='qc')return `<div class="rf-guided-heading"><span>STAP 4 VAN 5</span><h3>Herstelling en eindcontrole</h3><p>Voer de herstelling uit en controleer daarna het toestel.</p></div>${r.status==='In reparatie'?`<div class="rf-guided-next"><p>Is de herstelling uitgevoerd? Start dan de eindcontrole.</p><button class="btn g" data-action="repair-transition" data-status="Kwaliteitscontrole" data-ticket="${esc(ticket)}">Start eindcontrole →</button></div>`:''}<div class="grid2"><div class="demo-card"><h3>Controle na herstelling</h3><p>Vink alleen controles aan die je werkelijk hebt uitgevoerd en goedgekeurd.</p>${QC.map(x=>`<label><input class="check qcbox" type="checkbox" data-qc="${esc(x)}" ${r.qc[x]?'checked':''}> ${esc(x)}</label>`).join('')}<button class="btn g" data-action="repair-save-qc" data-ticket="${esc(ticket)}">Controle bewaren</button></div><div class="demo-card"><h3>Resultaat</h3><h2>${r.qcComplete?'✓ QC geslaagd':'Nog niet volledig'}</h2>${r.qcComplete&&r.status==='Kwaliteitscontrole'?`<button class="btn g" data-action="repair-mark-ready" data-ticket="${esc(ticket)}">Markeer als klaar</button>`:''}</div></div>`;
if(activeRepairTab==='payment')return `<div class="rf-guided-heading"><span>STAP 5 VAN 5</span><h3>Afhaling en betaling</h3><p>Controleer of het toestel klaar is en of er nog een bedrag openstaat.</p></div>${r.status!=='Klaar'&&r.status!=='Afgehaald'?'<p class="rf-guided-notice">Het toestel is nog niet als klaar geregistreerd. Afhalen kan pas na een geslaagde eindcontrole.</p>':''}<div class="grid2"><div class="demo-card"><h3>Betalingsoverzicht</h3><p>Offerte ${euro(quoteAmount(r))}<br>Betaald ${euro(paidTotal(r))}</p><h2>Open ${euro(due(r))}</h2><button class="btn g" data-action="repair-payment-new" data-ticket="${esc(ticket)}" ${due(r)<=0?'disabled':''}>Betaling registreren</button>${r.status==='Klaar'&&due(r)<=0?`<button class="btn g" data-action="pickup" data-ticket="${esc(ticket)}">Afhaling bevestigen</button>`:''}</div><div><h3>Transacties</h3>${r.payments.slice().reverse().map(p=>`<div class="demo-card" style="margin:8px 0"><b>${esc(p.ref)}</b> · ${euro(p.amount)}<br>${esc(p.type)} · ${esc(p.method)} · ${esc(p.at)}</div>`).join('')||'<p>Geen betalingen.</p>'}</div></div>`;
if(activeRepairTab==='documents')return `<div class="row space wrap"><h3>Documenten</h3><div class="toolbar"><button class="btn g" data-action="repair-doc-create" data-ticket="${esc(ticket)}">+ Reparatieverslag</button><button class="btn s" data-action="print-preview" data-mode="sticker" data-ticket="${esc(ticket)}">Sticker</button><button class="btn s" data-action="print-preview" data-mode="receipt" data-ticket="${esc(ticket)}">Klantbon</button></div></div><div class="grid3">${r.documents.map(d=>`<div class="demo-card"><h3>${esc(d)}</h3><button class="btn s" data-action="doc-preview" data-ticket="${esc(ticket)}" data-doc="${esc(d)}">Open/print</button></div>`).join('')}</div>`;
return `<h3>Gestructureerde audit</h3><div class="field"><label>Filter</label><input id="auditFilter" placeholder="bv. status, offerte, betaling..."></div><div id="auditRows">${auditHtml(r,'')}</div>`;}
function auditHtml(r,q){q=(q||'').toLowerCase();return r.audit.filter(a=>[a.at,a.actor,a.action,a.oldValue,a.newValue,a.source].join(' ').toLowerCase().includes(q)).map(a=>`<div class="demo-card" style="margin:8px 0"><b>${esc(a.action)}</b><br><span class="small muted">${esc(a.at)} · ${esc(a.actor)} · ${esc(a.source)}</span>${a.oldValue||a.newValue?`<p class="small">Oud: ${esc(a.oldValue||'—')}<br>Nieuw: ${esc(a.newValue||'—')}</p>`:''}</div>`).join('')||'<p>Geen auditregels gevonden.</p>';}
function overviewActions(ticket,r){if(r.status==='Binnengebracht')return`<button class="btn g" data-action="repair-transition" data-status="Diagnose" data-ticket="${esc(ticket)}">Start diagnose</button>`;if(r.status==='Diagnose')return`<button class="btn g" data-action="repair-tab" data-tab="diagnosis" data-ticket="${esc(ticket)}">Diagnose</button><button class="btn s" data-action="repair-tab" data-tab="quote" data-ticket="${esc(ticket)}">Offerte</button>`;if(r.status==='Wachten op klant')return`<button class="btn g" data-action="track" data-ticket="${esc(ticket)}">Klantbeslissing openen</button>`;if(r.status==='Wachten op onderdeel')return`<button class="btn g" data-action="repair-tab" data-tab="parts" data-ticket="${esc(ticket)}">Onderdelen</button>`;if(r.status==='In reparatie')return`<button class="btn g" data-action="repair-transition" data-status="Kwaliteitscontrole" data-ticket="${esc(ticket)}">Naar QC</button>`;if(r.status==='Kwaliteitscontrole')return`<button class="btn g" data-action="repair-tab" data-tab="qc" data-ticket="${esc(ticket)}">QC-test</button>`;if(r.status==='Klaar')return`<button class="btn g" data-action="repair-tab" data-tab="payment" data-ticket="${esc(ticket)}">Betaling / afhaling</button>`;return'';}
function newRepair(){
overlay('Nieuwe reparatie',`<div class="rf-intake">
<header class="rf-intake-head"><span class="rf-intake-kicker">REPARATIE AANMELDEN</span><h2>Nieuw toestel aannemen</h2><p>Drie eenvoudige stappen. Alleen de belangrijkste gegevens zijn verplicht.</p></header>
<div class="rf-intake-steps" aria-label="Voortgang"><div class="rf-intake-step" data-rn-indicator="0"><span>1</span> Klant</div><div class="rf-intake-step" data-rn-indicator="1"><span>2</span> Toestel</div><div class="rf-intake-step" data-rn-indicator="2"><span>3</span> Bevestigen</div></div>
<div class="rf-intake-body">
<section data-rn-step="0"><h3>Wie brengt het toestel binnen?</h3><p class="rf-intake-hint">Zo kunnen we de klant later gemakkelijk terugvinden.</p><div class="rf-intake-field"><label for="rnName">Naam klant <em>*</em></label><input id="rnName" autocomplete="name" placeholder="Voor- en achternaam" required></div><div class="rf-intake-two"><div class="rf-intake-field"><label for="rnPhone">Telefoonnummer</label><input id="rnPhone" type="tel" autocomplete="tel" placeholder="04…"></div><div class="rf-intake-field"><label for="rnEmail">E-mailadres</label><input id="rnEmail" type="email" autocomplete="email" placeholder="naam@voorbeeld.be"></div></div></section>
<section data-rn-step="1" hidden><h3>Wat is er met het toestel?</h3><p class="rf-intake-hint">Noteer de klacht zoals de klant die beschrijft.</p><div class="rf-intake-two"><div class="rf-intake-field"><label for="rnType">Type toestel</label><select id="rnType"><option>Smartphone</option><option>Tablet</option><option>Laptop</option><option>Console</option><option>Overig</option></select></div><div class="rf-intake-field"><label for="rnDevice">Merk en model <em>*</em></label><input id="rnDevice" placeholder="Bijv. Samsung Galaxy S24" required></div></div><div class="rf-intake-field"><label for="rnProblem">Wat is het probleem? <em>*</em></label><textarea id="rnProblem" rows="4" placeholder="Bijv. het toestel laadt niet meer op" required></textarea></div><div class="rf-intake-field"><label for="rnSerial">IMEI / serienummer <small>optioneel</small></label><input id="rnSerial" placeholder="Scan of typ het nummer"></div></section>
<section data-rn-step="2" hidden><h3>Alles correct?</h3><p class="rf-intake-hint">Controleer de gegevens voordat je het dossier aanmaakt.</p><div class="rf-intake-summary" id="rnSummary"></div>
<details class="rf-intake-extra"><summary>Extra gegevens toevoegen <small>(optioneel)</small></summary><div class="rf-intake-extra-fields"><div class="rf-intake-two"><div class="rf-intake-field"><label for="rnLocation">Bak / locatie</label><input id="rnLocation" placeholder="Bijv. Bak A4"></div><div class="rf-intake-field"><label for="rnPriority">Prioriteit</label><select id="rnPriority"><option>Laag</option><option selected>Normaal</option><option>Hoog</option><option>Spoed</option></select></div></div><div class="rf-intake-field"><label for="rnAccessories">Meegeleverde accessoires</label><input id="rnAccessories" placeholder="Bijv. hoesje, lader"></div><div class="rf-intake-field"><label for="rnDamage">Zichtbare schade bij ontvangst</label><textarea id="rnDamage" rows="2" placeholder="Bijv. kras linksboven"></textarea></div><div class="rf-intake-field"><label for="rnUnlock">Toegangscode <small>alleen indien noodzakelijk</small></label><input id="rnUnlock" type="password" autocomplete="off"></div></div></details>
<button class="btn g rf-intake-submit" data-action="repair-create" type="button">Reparatie aanmelden ✓</button></section>
<p id="rnError" role="alert" class="rf-intake-error" aria-live="polite"></p>
<div class="rf-intake-footer"><button class="btn s" id="rnBack" type="button">← Vorige</button><span id="rnStepLabel" class="rf-intake-count">Stap 1 van 3</span><button class="btn g" id="rnNext" type="button">Verder →</button></div>
</div></div>`);
let step=0;
const show=()=>{
 document.querySelectorAll('#oc [data-rn-step]').forEach(x=>{x.hidden=Number(x.dataset.rnStep)!==step});
 document.querySelectorAll('#oc [data-rn-indicator]').forEach(x=>x.classList.toggle('active',Number(x.dataset.rnIndicator)===step));
 $('rnStepLabel').textContent='Stap '+(step+1)+' van 3';
 $('rnBack').hidden=step===0;$('rnNext').hidden=step===2;$('rnError').textContent='';
 if(step===2)$('rnSummary').innerHTML='<div><small>Klant</small><strong>'+esc($('rnName').value.trim())+'</strong></div><div><small>Toestel</small><strong>'+esc($('rnDevice').value.trim())+'</strong></div><div><small>Probleem</small><strong>'+esc($('rnProblem').value.trim())+'</strong></div>';
};
$('rnBack').addEventListener('click',()=>{if(step>0){step--;show()}});
$('rnNext').addEventListener('click',()=>{
 const name=$('rnName').value.trim(),device=$('rnDevice').value.trim(),problem=$('rnProblem').value.trim();
 if(step===0&&!name){$('rnError').textContent='Vul de naam van de klant in.';$('rnName').focus();return}
 if(step===0&&$('rnEmail').value.trim()&&!$('rnEmail').checkValidity()){$('rnError').textContent='Controleer het e-mailadres.';$('rnEmail').focus();return}
 if(step===1&&(!device||!problem)){$('rnError').textContent='Vul het toestel en het probleem in.';(!device?$('rnDevice'):$('rnProblem')).focus();return}
 if(step<2){step++;show()}
});
show();
}
document.addEventListener('change',async e=>{if(e.target?.id!=='rfPhotoFile')return;const f=e.target.files?.[0],ticket=selected,r=repairs[ticket];if(!f||!r)return;if(!f.type.startsWith('image/')){toast('Kies een afbeelding.');return;}if(f.size>12*1024*1024){toast('Foto is te groot (maximaal 12 MB).');return;}if((r.photoImages||[]).length>=4){toast('Maximaal vier foto’s.');return;}try{const img=new Image(),url=URL.createObjectURL(f);await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const ratio=Math.min(1,900/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);const data=canvas.toDataURL('image/jpeg',.65);r.photoImages=Array.isArray(r.photoImages)?r.photoImages:[];r.photoImages.push({data,at:now()});r.photos=r.photoImages.length;save();log(r,'Ontvangstfoto toegevoegd','','Foto '+r.photos);save();detail(ticket,'intake');toast('Foto opgeslagen');}catch(err){toast('Foto kon niet opgeslagen worden. Controleer de opslagruimte.');}});
function paymentForm(ticket){const r=repairs[ticket];overlay('Betaling / voorschot · '+ticket,`<div class="oc"><h2>Open saldo ${euro(due(r))}</h2><label>Bedrag</label><input id="payAmount" type="number" min="0.01" step="0.01" value="${due(r).toFixed(2)}"><label>Type</label><select id="payType"><option>Betaling</option><option>Voorschot</option></select><label>Methode</label><select id="payMethod"><option>SumUp</option><option>Cash</option><option>Overschrijving</option><option>Bancontact</option><option>Andere</option></select><button class="btn g" data-action="repair-payment-start" data-ticket="${esc(ticket)}">Betaling starten</button></div>`);}
function renderTicketQR(ticket){
 const target=document.getElementById('rfTicketQr');if(!target)return;
 target.replaceChildren();
 if(typeof QRCode!=='function'){target.textContent='QR-code niet beschikbaar. Gebruik het dossiernummer.';return}
 try{
  new QRCode(target,{text:String(ticket),width:150,height:150,colorDark:'#000000',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});
  const canvas=target.querySelector('canvas'),img=target.querySelector('img');
  if(canvas&&img){try{img.src=canvas.toDataURL('image/png');img.style.display='block';canvas.remove()}catch(e){img.remove();canvas.style.display='block'}}
 }catch(e){target.textContent='QR-code kon niet gemaakt worden. Gebruik het dossiernummer.'}
}
function trackView(ticket){selected=ticket;const r=repairs[ticket],q=currentQuote(r),meta=STATUS_META[r.status]||{};overlay('Klant Track & Trace · '+ticket,`<div class="oc" style="max-width:650px;margin:auto"><div style="background:#0f172a;color:#fff;border-radius:14px;padding:18px"><div class="small" style="opacity:.8">RepairFlow · ${esc(ticket)}</div><h1 style="margin:4px 0">${esc(r.device)}</h1><div>${esc(r.name)}</div></div><div style="text-align:center;padding:18px 0"><span class="small muted">ACTUELE STATUS</span><h2>${esc(meta.label||r.status)}</h2><p>${esc(meta.desc||'')}</p>${progress(r)}</div>${q?`<div class="demo-card"><span class="small muted">Prijsopgave v${q.version}</span><h1>${euro(q.amount)}</h1><p>${esc(q.note)}</p>${q.status==='open'?`<p class="small muted">Offerte is alleen opgeslagen. Geen verzending of online klantgoedkeuring gekoppeld.</p><div class="toolbar"><button class="btn g" data-action="quote-decision-open" data-decision="approved" data-ticket="${esc(ticket)}">Klantakkoord registreren</button><button class="btn r" data-action="quote-decision-open" data-decision="rejected" data-ticket="${esc(ticket)}">Weigering registreren</button></div>`:`<b>${esc(q.status)}</b>`}</div>`:''}<div class="demo-card" style="margin-top:12px"><h3>Gemelde klacht</h3><p>${esc(r.customerStatementOriginal)}</p></div><div class="demo-card" style="margin-top:12px"><h3>Betaling & afhaling</h3><p>Betaald ${euro(paidTotal(r))} · open ${euro(due(r))}</p><p>${r.status==='Klaar'?'✓ Toestel klaar voor afhaling.':'Kom pas langs wanneer de status Klaar voor afhaling is.'}</p></div><div class="demo-card" style="margin-top:12px;text-align:center"><b>QR-code van het reparatiedossier</b><p class="small">${esc(ticket)}</p><div id="rfTicketQr" style="width:170px;min-height:170px;margin:12px auto;background:#fff;padding:10px;display:grid;place-items:center"></div><p class="small muted">Scan voor dossiernummer ${esc(ticket)}. Er is nog geen openbaar klantenportaal.</p></div></div>`);renderTicketQR(ticket);}
// PHIXAR document identity. The owner must update/confirm the KBO address before legal invoicing.
const PHIXAR_DOCUMENTS=Object.freeze({tradeName:'PHIXAR',legalName:'Gihana, Marcelin',vat:'BE 0805.990.222',street:'Brusselsesteenweg 103',city:'9050 Gent'});
function printPreview(ticket,mode){
 const r=repairs[ticket];if(!r){toast('Dossier niet gevonden.');return}
 const q=currentQuote(r),label=mode==='sticker',valid=v=>v&&v!=='Niet opgegeven'&&v!=='Onbekend toestel';
 const detailLine=(title,value)=>valid(value)?`<div class="rf-paper-row"><span>${title}</span><strong>${esc(value)}</strong></div>`:'';
 const qr=`<div class="rf-paper-qr"><div id="rfTicketQr"></div><span>SCAN DOSSIERNUMMER</span></div>`;
 const sticker=`<div id="printDoc" class="rf-paper rf-paper-label"><div class="rf-paper-label-head"><b>PHI<span class="rf-phixar-x">X</span>AR</b><span>REVIVE · REPAIR · RESTORE</span></div><div class="rf-paper-label-main"><div class="rf-paper-label-copy"><strong class="rf-paper-device">${esc(r.device)}</strong><b class="rf-paper-ticket">${esc(ticket)}</b><span class="rf-paper-label-name">${esc(r.name)}</span>${detailLine('IMEI / S/N',r.serial)}${detailLine('Locatie',r.location)}</div>${qr}</div><div class="rf-paper-label-foot"><span>${esc(r.status)}</span><span>${esc(new Date().toLocaleDateString('nl-BE'))}</span></div></div>`;
 const receipt=`<div id="printDoc" class="rf-paper rf-paper-receipt"><header class="rf-paper-receipt-head"><div><div class="rf-paper-brand">PHI<span class="rf-phixar-x">X</span>AR</div><div class="rf-paper-subtitle">REVIVE · REPAIR · RESTORE</div><div class="rf-paper-business-service">Smartphoneherstellingen &amp; accessoires</div><div class="rf-paper-business-address">${esc(PHIXAR_DOCUMENTS.street)} · ${esc(PHIXAR_DOCUMENTS.city)}</div><div class="rf-paper-business-legal">${esc(PHIXAR_DOCUMENTS.legalName)} · BTW ${esc(PHIXAR_DOCUMENTS.vat)}</div><div class="rf-paper-document-title">Ontvangstbewijs reparatie</div></div><div class="rf-paper-date">${esc(new Date().toLocaleDateString('nl-BE'))}</div></header><div class="rf-paper-ticket-hero"><span>REPARATIENUMMER</span><strong>${esc(ticket)}</strong><small>Status: ${esc(r.status)}</small></div><div class="rf-paper-section"><h3>Klant</h3>${detailLine('Naam',r.name)}${detailLine('Telefoon',r.phone)}${detailLine('E-mail',r.email)}</div><div class="rf-paper-section"><h3>Toestel</h3>${detailLine('Model',r.device)}${detailLine('IMEI / S/N',r.serial)}${detailLine('Locatie',r.location)}${detailLine('Accessoires',r.accessories)}<div class="rf-paper-problem"><span>Gemelde klacht</span><p>${esc(r.customerStatementOriginal||'Niet opgegeven')}</p></div></div><div class="rf-paper-section"><h3>Prijs en opvolging</h3><div class="rf-paper-row"><span>Offerte</span><strong>${q?euro(q.amount):'Nog niet opgesteld'}</strong></div><div class="rf-paper-row"><span>Ontvangen betaling</span><strong>${euro(paidTotal(r))}</strong></div><p class="rf-paper-note">Dit is een ontvangstbewijs, geen factuur of betalingsbewijs. Een offerte is pas goedgekeurd na registratie van het klantakkoord.</p></div><div class="rf-paper-receipt-qr">${qr}<div><b>Bewaar dit ontvangstbewijs</b><p>De QR-code bevat alleen het reparatienummer. Online statusopvolging is nog niet beschikbaar.</p></div></div><footer class="rf-paper-footer">PHIXAR · ${esc(PHIXAR_DOCUMENTS.street)}, ${esc(PHIXAR_DOCUMENTS.city)} · www.phixar.be · ${esc(ticket)}</footer></div>`;
 overlay(label?'Toestellabel · 60 × 40 mm':'Ontvangstbewijs · A4 / PDF',`<div class="rf-paper-preview"><div class="rf-paper-preview-inner">${label?sticker:receipt}</div></div><div class="toolbar rf-paper-actions"><button class="btn s" data-action="print-switch" data-mode="sticker" data-ticket="${esc(ticket)}">Toestellabel</button><button class="btn s" data-action="print-switch" data-mode="receipt" data-ticket="${esc(ticket)}">Ontvangstbewijs</button><button class="btn g" data-action="print-doc">Afdrukken / PDF</button></div>`);
 const target=document.getElementById('rfTicketQr');if(target&&typeof QRCode==='function'){target.replaceChildren();try{new QRCode(target,{text:String(ticket),width:label?78:116,height:label?78:116,colorDark:'#000000',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});const canvas=target.querySelector('canvas'),img=target.querySelector('img');if(canvas&&img){img.src=canvas.toDataURL('image/png');img.style.display='block';canvas.remove()}else if(canvas){canvas.style.display='block'}}catch(e){target.textContent=esc(ticket)}}else if(target){target.textContent=esc(ticket)}
}
function docPreview(ticket,name){const r=repairs[ticket],q=currentQuote(r);overlay(name,`<div class="oc" id="printDoc"><h1>PHIXAR</h1><p>${esc(PHIXAR_DOCUMENTS.street)}, ${esc(PHIXAR_DOCUMENTS.city)} · ${esc(PHIXAR_DOCUMENTS.legalName)} · BTW ${esc(PHIXAR_DOCUMENTS.vat)}</p><h2>${esc(name)}</h2><p><b>Dossier:</b> ${esc(ticket)}<br><b>Klant:</b> ${esc(r.name)}<br><b>Toestel:</b> ${esc(r.device)}<br><b>IMEI/serial:</b> ${esc(r.serial)}</p><hr><p><b>Klacht klant:</b><br>${esc(r.customerStatementOriginal)}</p><p><b>Diagnose:</b><br>${esc(r.diagnosis||'—')}</p><p><b>Offerte:</b> ${q?euro(q.amount):'—'}<br><b>Betaald:</b> ${euro(paidTotal(r))}</p><p class="small">Gegenereerd ${esc(now())}</p></div><button class="btn g" data-action="print-doc">Afdrukken / PDF</button>`);}
const MODULES={customers:'Klanten',refurb:'Refurbished',sales:'Kassa',parts:'Voorraad',payments:'Betalingen',invoices:'Verkoopbewijzen',accounting:'Bedrijfsoverzicht',reports:'Rapporten',warranty:'Garantie',employees:'Medewerkers',audit:'Auditlog',settings:'Instellingen'};
function moduleDemo(type){overlay(MODULES[type]||'Module',`<div class="oc"><h2>${esc(MODULES[type]||type)}</h2><p>Deze functie is nog niet beschikbaar.</p></div>`);}
function kiosk(){overlay('RepairFlow Intake · veilige kiosk','<h1 style="text-align:center">Welkom 👋</h1><p style="text-align:center">Hoe wilt u zich registreren?</p><div class="choices"><button class="choice" data-action="kiosk-form" data-type="Particulier">👤<br>Particulier</button><button class="choice" data-action="kiosk-form" data-type="Bedrijf">🏢<br>Bedrijf</button></div>');}
function kioskForm(type){overlay('Nieuwe reparatie · '+type,`<div class="oc">${type==='Bedrijf'?'<label>BTW-/ondernemingsnummer *</label><div class="row"><input id="vat" placeholder="BE 0123.456.789"></div><div id="company"></div>':''}<label>${type==='Bedrijf'?'Contactpersoon':'Naam'} *</label><input id="nm"><label>Telefoon</label><input id="ph"><label>E-mail</label><input id="em"><label>Type toestel</label><select id="kt"><option>Smartphone</option><option>Laptop</option><option>Tablet</option><option>Console</option></select><label>Merk & model *</label><input id="dv"><label>IMEI / serienummer</label><input id="sr"><label>Probleemomschrijving *</label><textarea id="pr"></textarea><label><input id="cf" class="check" type="checkbox"> Ik bevestig dat dit mijn probleemomschrijving is.</label><br><button class="btn g" data-action="submit">Intake bevestigen</button></div>`);}
document.addEventListener('input',e=>{if(e.target.id==='repairSearch')renderRepairList();if(e.target.id==='auditFilter'){const r=repairs[selected];if($('auditRows'))$('auditRows').innerHTML=auditHtml(r,e.target.value);}});
document.addEventListener('change',e=>{if(e.target.id==='repairFilter')renderRepairList();const a=e.target.closest('[data-action="repair-part-status"]');if(a){
 const r=repairs[a.dataset.ticket],p=r?.parts[Number(a.dataset.index)];if(!p)return;
 const old=p.status,requested=a.value;
 if(p.productId&&!p.reserved&&['received','reserved','used'].includes(requested)){
  if(!rfStockChange(p.productId,-p.qty,'Onderdeel ontvangen / gereserveerd',a.dataset.ticket)){toast('Onvoldoende voorraad. Boek eerst de levering in onder Voorraad.');detail(a.dataset.ticket,'quote');return}
  p.reserved=true;
 }
 if(p.productId&&p.reserved&&requested==='ordered'){
  if(!rfStockChange(p.productId,p.qty,'Onderdeelreservering vrijgegeven',a.dataset.ticket)){toast('Voorraad kon niet worden teruggeboekt.');detail(a.dataset.ticket,'quote');return}
  p.reserved=false;
 }
 p.status=requested;log(r,'Onderdeelstatus gewijzigd',old,p.status);
 if(p.status==='received'&&r.status==='Wachten op onderdeel')setStatus(r,'In reparatie');
 try{save()}catch(e){toast('Onderdeelstatus kon niet worden opgeslagen.');return}
 detail(a.dataset.ticket,'quote');
}});
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){go(nav.dataset.page);return}const a=e.target.closest('[data-action]');if(!a)return;const x=a.dataset.action;
if(x==='repair-view'){repairView=a.dataset.view;renderRepairList();}
else if(x==='repair-select'){selected=a.dataset.ticket;renderRepairList();}
else if(x==='repair-open-full'){activeRepairTab='overview';detail(a.dataset.ticket);}
else if(x==='repair-back'){repairView='board';renderRepairList();}
else if(x==='repair-new')newRepair();
else if(x==='repair-create'){const name=$('rnName').value.trim(),device=$('rnDevice').value.trim(),problem=$('rnProblem').value.trim();if(!name||!device||!problem){toast('Naam, toestel en probleemomschrijving zijn verplicht.');return}const ticket='REP-'+new Date().getFullYear()+'-'+String(++next).padStart(5,'0');repairs[ticket]=mk({name,phone:$('rnPhone').value.trim(),email:$('rnEmail').value.trim(),deviceType:$('rnType').value,device,serial:$('rnSerial').value.trim()||'Niet opgegeven',customerStatementOriginal:problem,damage:$('rnDamage').value.trim(),accessories:$('rnAccessories').value.trim(),unlock:$('rnUnlock').value,location:$('rnLocation').value.trim()||'Nog toe te wijzen',priority:$('rnPriority').value});log(repairs[ticket],'Originele klantverklaring vastgelegd','',problem);save();selected=ticket;closeOverlay();renderRepairList();toast('Dossier '+ticket+' aangemaakt');printPreview(ticket,'sticker');}
else if(x==='repair-tab'){detail(a.dataset.ticket,a.dataset.tab);}
else if(x==='repair-add-addendum'){const r=repairs[a.dataset.ticket],text=$('riAddendum').value.trim();if(!text){toast('Vul een addendum in.');return}r.customerAddenda.push({id:uid('ADD'),at:now(),text,actor:'Amine'});log(r,'Addendum klantverklaring toegevoegd','',text);save();detail(a.dataset.ticket,'intake');}
else if(x==='repair-save-intake'){const r=repairs[a.dataset.ticket];const fields=[['damage','riDamage','Zichtbare schade'],['accessories','riAccessories','Accessoires'],['tech','riTech','Technicusnotitie'],['priority','riPriority','Prioriteit'],['technician','riTechnician','Technicus'],['location','riLocation','Locatie'],['dueDate','riDue','Verwachte klaar-datum']];fields.forEach(([k,id,label])=>{const nv=$(id).value,ov=r[k];if(nv!==ov){r[k]=nv;log(r,label+' gewijzigd',ov,nv);}});const unlock=$('riUnlock').value;if(unlock!==r.unlock){r.unlock=unlock;log(r,'Toestelcode gewijzigd','[afgeschermd]',unlock?'[ingesteld]':'[gewist]');}save();detail(a.dataset.ticket,'intake');toast('Intake opgeslagen');}
else if(x==='repair-toggle-unlock'){const el=$('riUnlock');if(!el)return;el.type=el.type==='password'?'text':'password';const r=repairs[a.dataset.ticket];log(r,'Toestelcode bekeken','','','Amine','security');save();}
else if(x==='repair-transition'){const r=repairs[a.dataset.ticket];if(setStatus(r,a.dataset.status)){save();detail(a.dataset.ticket);}}
else if(x==='repair-save-diagnosis'){const r=repairs[a.dataset.ticket],hours=+$('rdHours').value,rate=+$('rdRate').value;if(!Number.isFinite(hours)||!Number.isFinite(rate)||hours<0||rate<0){toast('Controleer de werkuren en het tarief.');return}if(!$('rdDiagnosis').value.trim()){toast('Beschrijf eerst de diagnose.');return}const old=r.diagnosis;r.diagnosis=$('rdDiagnosis').value.trim();r.tests=$('rdTests').value.trim();r.outcome=$('rdOutcome').value;r.laborHours=hours||0;r.laborRate=rate||0;log(r,'Diagnose opgeslagen',old,r.diagnosis);if(r.status==='Binnengebracht')setStatus(r,'Diagnose');if(r.outcome==='Niet herstelbaar'&&r.status==='Diagnose')setStatus(r,'Wachten op klant');save();detail(a.dataset.ticket,'diagnosis');toast('Diagnose bewaard. Je kunt nu de offerte opstellen.');}
else if(x==='repair-add-part'){const options=rfSharedProducts().filter(p=>p.active!==false);overlay('Onderdeel toevoegen',`<div class="oc"><p class="muted">Gebruik artikelen uit de centrale kassavoorraad. Voeg ontbrekende onderdelen eerst toe onder Voorraad.</p><label>Artikel</label><select id="rpPart">${options.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · voorraad ${p.stock} · ${euro(p.price)}</option>`).join('')}</select><label>Aantal</label><input id="rpQty" type="number" value="1" min="1" step="1">${options.length?`<button class="btn g" data-action="repair-part-save" data-ticket="${esc(a.dataset.ticket)}">Toevoegen</button>`:'<p>Geen artikelen gevonden. Maak eerst een artikel aan bij Voorraad.</p>'}</div>`);}
else if(x==='repair-part-save'){
 const r=repairs[a.dataset.ticket],productId=$('rpPart')?.value,qty=Number($('rpQty')?.value);
 const item=rfSharedProducts().find(p=>p.id===productId&&p.active!==false);
 if(!r||!item||!Number.isInteger(qty)||qty<1){toast('Kies een geldig artikel en aantal.');return}
 const reserved=item.stock>=qty;
 if(reserved&&!rfStockChange(productId,-qty,'Gereserveerd voor reparatie',a.dataset.ticket)){toast('Voorraad reserveren mislukt.');return}
 const part={id:uid('P'),productId,name:item.name,qty,cost:item.cost,price:item.price,status:reserved?'reserved':'ordered',reserved};
 r.parts.push(part);log(r,'Onderdeel toegevoegd','',item.name+' x'+qty+' ('+part.status+')');
 if(!reserved&&r.status!=='Wachten op onderdeel'&&(TRANSITIONS[r.status]||[]).includes('Wachten op onderdeel'))setStatus(r,'Wachten op onderdeel');
 try{save()}catch(e){r.parts.pop();if(reserved)rfStockChange(productId,qty,'Herstel mislukte reservering',a.dataset.ticket);toast('Dossier kon niet worden opgeslagen.');return}
 closeOverlay();detail(a.dataset.ticket,'quote');toast(reserved?'Onderdeel gereserveerd':'Onderdeel te bestellen');
}
else if(x==='repair-remove-part'){
 const r=repairs[a.dataset.ticket],index=Number(a.dataset.index),p=r?.parts[index];if(!p)return;
 if(p.reserved&&p.status==='used'){toast('Gebruikt onderdeel kan niet zonder correctie worden verwijderd.');return}if(p.reserved&&p.productId&&!rfStockChange(p.productId,p.qty,'Reservering vrijgegeven',a.dataset.ticket)){toast('Voorraad terugboeken mislukt.');return}
 if(p.reserved&&!p.productId&&inventory[p.name])inventory[p.name].stock+=p.qty;
 r.parts.splice(index,1);log(r,'Onderdeel verwijderd',p.name,'');
 try{save()}catch(e){r.parts.splice(index,0,p);if(p.reserved&&p.productId)rfStockChange(p.productId,-p.qty,'Herstel verwijdering',a.dataset.ticket);toast('Dossier kon niet worden opgeslagen.');return}
 detail(a.dataset.ticket,'quote');
}
else if(x==='repair-save-quote'){const r=repairs[a.dataset.ticket],amount=+$('rqAmount').value,other=+$('rqOther').value;if(!Number.isFinite(amount)||!Number.isFinite(other)||amount<0||other<0){toast('Controleer de offertebedragen.');return}r.otherCost=other;const prev=currentQuote(r);if(prev&&['open','approved'].includes(prev.status))prev.status='superseded';const q={id:uid('Q'),version:(prev?.version||0)+1,amount,note:$('rqNote').value.trim(),status:'open',createdAt:now()};r.quotes.push(q);log(r,'Offerteversie aangemaakt',prev?`v${prev.version} ${euro(prev.amount)}`:'',`v${q.version} ${euro(q.amount)}`);if((TRANSITIONS[r.status]||[]).includes('Wachten op klant'))setStatus(r,'Wachten op klant');if(!r.documents.includes('Offerte'))r.documents.push('Offerte');save();detail(a.dataset.ticket,'quote');toast('Offerte v'+q.version+' opgeslagen. Versturen naar de klant is nog niet gekoppeld.');}
else if(x==='repair-save-qc'){const r=repairs[a.dataset.ticket];QC.forEach(k=>r.qc[k]=!!document.querySelector(`[data-qc="${CSS.escape(k)}"]`)?.checked);r.qcComplete=QC.every(k=>r.qc[k]);log(r,'QC-test opgeslagen','',r.qcComplete?'Geslaagd':'Onvolledig');save();detail(a.dataset.ticket,'qc');toast(r.qcComplete?'QC geslaagd':'QC nog onvolledig');}
else if(x==='repair-mark-ready'){const r=repairs[a.dataset.ticket];if(!r.qcComplete){toast('QC moet volledig geslaagd zijn.');return}if(setStatus(r,'Klaar')){log(r,'Toestel klaar na QC');save();detail(a.dataset.ticket);}}
else if(x==='repair-payment-new')paymentForm(a.dataset.ticket);
else if(x==='repair-payment-start'){
 const ticket=a.dataset.ticket,method=$('payMethod')?.value,amount=Number($('payAmount')?.value),type=$('payType')?.value;
 if(!Number.isFinite(amount)||amount<=0){toast('Vul een geldig bedrag in.');return}
 if(method==='SumUp'){
  overlay('Kaartbetaling',`<div class="oc"><h2>SumUp niet gekoppeld</h2><p>Er is geen betaalterminal gekoppeld. Registreer geen kaartbetaling zonder een echte bevestiging op de terminal.</p><button class="btn s" data-action="close">Sluiten</button></div>`);
 }else if(method==='Overschrijving'){
  overlay('Overschrijving',`<div class="oc"><p>Registreer de betaling pas nadat de overschrijving daadwerkelijk op de rekening staat.</p><button class="btn g" data-action="repair-payment-confirm" data-ticket="${esc(ticket)}" data-method="Overschrijving" data-amount="${esc(amount)}" data-type="${esc(type)}">Betaling daadwerkelijk ontvangen</button></div>`);
 }else if(confirm('Bevestig dat '+euro(amount)+' daadwerkelijk ontvangen is via '+method+'?'))confirmPayment(ticket,amount,type,method);
}
else if(x==='repair-payment-confirm'){if(confirm('Is deze betaling daadwerkelijk ontvangen?'))confirmPayment(a.dataset.ticket,+a.dataset.amount,a.dataset.type,a.dataset.method);}
else if(x==='pickup'){const r=repairs[a.dataset.ticket];if(r.status!=='Klaar'){toast('Toestel moet eerst Klaar zijn.');return}if(due(r)>0){toast('Er staat nog een saldo open.');return}if(!r.qcComplete){toast('QC is niet volledig.');return}if(setStatus(r,'Afgehaald')){if(r.unlock){r.unlock='';log(r,'Toestelcode automatisch gewist','[ingesteld]','[gewist]','systeem','security');}r.warranty=true;log(r,'Garantie gestart');save();detail(a.dataset.ticket);toast('Afgehaald · garantie actief');}}
else if(x==='repair-doc-create'){const r=repairs[a.dataset.ticket],name='Reparatieverslag '+(r.documents.filter(x=>x.startsWith('Reparatieverslag')).length+1);r.documents.push(name);log(r,'Document gegenereerd','',name);save();detail(a.dataset.ticket,'documents');}
else if(x==='doc-preview')docPreview(a.dataset.ticket,a.dataset.doc);
else if(x==='print-preview')printPreview(a.dataset.ticket,a.dataset.mode);
else if(x==='print-switch')printPreview(a.dataset.ticket,a.dataset.mode);
else if(x==='print-doc')window.print();
else if(x==='track')trackView(a.dataset.ticket);
else if(x==='confirmphotos'){
 const r=repairs[a.dataset.ticket];if(!r)return;
 overlay('Fotobevestiging registreren',`<div class="oc"><p>Dit is een handmatige registratie door een medewerker, geen digitale handtekening van de klant.</p><label>Hoe heeft de klant de foto's bevestigd?</label><select id="rfPhotoChannel"><option value="">Kies bevestigingswijze</option><option>Persoonlijk in winkel</option><option>Telefonisch</option><option>E-mail</option></select><label>Notitie / bewijsreferentie *</label><textarea id="rfPhotoEvidence" placeholder="Bijv. klant heeft foto's aan balie bekeken"></textarea><button class="btn g" data-action="confirmphotos-save" data-ticket="${esc(a.dataset.ticket)}">Bevestiging registreren</button></div>`);
}
else if(x==='confirmphotos-save'){
 const r=repairs[a.dataset.ticket],channel=$('rfPhotoChannel')?.value,evidence=$('rfPhotoEvidence')?.value.trim();
 if(!r||!channel||!evidence){toast('Vul de bevestigingswijze en bewijsnotitie in.');return}
 r.photoConfirmed=true;r.photoConfirmation={at:new Date().toISOString(),channel,evidence,recordedBy:'Medewerker'};
 log(r,'Fotobevestiging handmatig geregistreerd','',channel+' · '+evidence,'Medewerker','handmatige registratie');
 try{save()}catch(e){r.photoConfirmed=false;delete r.photoConfirmation;r.audit.shift();toast('Opslaan mislukt.');return}
 closeOverlay();detail(a.dataset.ticket,'intake');
}
else if(x==='quote-decision-open'){
 const r=repairs[a.dataset.ticket],q=r&&currentQuote(r),decision=a.dataset.decision;
 if(!q||q.status!=='open'||!['approved','rejected'].includes(decision)){toast('Geen open offerte.');return}
 overlay('Klantbeslissing vastleggen',`<div class="oc"><p>Offerte v${q.version} · ${euro(q.amount)}. Registreer alleen een beslissing die de klant daadwerkelijk heeft meegedeeld. Dit scherm stuurt niets naar de klant.</p><label>Contactkanaal *</label><select id="rfQuoteChannel"><option value="">Selecteer</option><option>Persoonlijk in winkel</option><option>Telefonisch</option><option>E-mail</option><option>Bericht</option></select><label>Bewijs of toelichting *</label><textarea id="rfQuoteEvidence" placeholder="Bijv. e-mail akkoord ontvangen op datum, of telefonisch gesprek"></textarea><button class="btn g" data-action="quote-decision-save" data-ticket="${esc(a.dataset.ticket)}" data-decision="${esc(decision)}">Beslissing vastleggen</button></div>`);
}
else if(x==='quote-decision-save'){
 const r=repairs[a.dataset.ticket],q=r&&currentQuote(r),decision=a.dataset.decision,channel=$('rfQuoteChannel')?.value,evidence=$('rfQuoteEvidence')?.value.trim();
 if(!q||q.status!=='open'||!['approved','rejected'].includes(decision)||!channel||!evidence){toast('Vul contactkanaal en bewijsnotitie in.');return}
 const previousStatus=r.status,previousAudit=r.audit.length;
 q.status=decision;q.decisionAt=new Date().toISOString();q.decisionChannel=channel;q.decisionEvidence=evidence;q.decisionRecordedBy='Medewerker';
 log(r,'Klantbeslissing handmatig geregistreerd','',`v${q.version} · ${decision} · ${channel} · ${evidence}`,'Medewerker','handmatige registratie');
 if(decision==='approved'&&r.status==='Wachten op klant'){
  const waiting=r.parts.some(p=>p.status==='ordered');setStatus(r,waiting?'Wachten op onderdeel':'In reparatie');
 }
 try{save()}catch(e){q.status='open';delete q.decisionAt;delete q.decisionChannel;delete q.decisionEvidence;delete q.decisionRecordedBy;r.status=previousStatus;r.audit.splice(0,r.audit.length-previousAudit);toast('Opslaan mislukt.');return}
 closeOverlay();detail(a.dataset.ticket,'quote');toast('Klantbeslissing geregistreerd (handmatig).');
}
else if(x==='kiosk')kiosk();else if(x==='kiosk-form')kioskForm(a.dataset.type);else if(x==='submit'){if(!$('cf').checked){toast('Bevestig eerst de verklaring.');return}const problem=$('pr').value.trim(),name=$('nm').value.trim(),device=$('dv').value.trim();if(!problem||!name||!device){toast('Naam, toestel en probleem zijn verplicht.');return}const ticket='REP-'+new Date().getFullYear()+'-'+String(++next).padStart(5,'0');repairs[ticket]=mk({name,phone:$('ph').value.trim(),email:$('em').value.trim(),deviceType:$('kt').value,device,serial:$('sr').value.trim()||'Niet opgegeven',customerStatementOriginal:problem});log(repairs[ticket],'Originele klantverklaring bevestigd','',problem,'Klant','kiosk');save();selected=ticket;overlay('Reparatie aangemeld',`<div class="oc"><h2>Reparatie geregistreerd</h2><b>${esc(ticket)}</b><p>${esc(name)}<br>${esc(device)}</p><button class="btn g" data-action="employee-open" data-ticket="${esc(ticket)}">Open intake & maak foto’s</button></div>`);}
else if(x==='employee-open'){closeOverlay();activeRepairTab='intake';detail(a.dataset.ticket,'intake');}
else if(x==='close')closeOverlay();
else if(x==='module')moduleDemo(a.dataset.module);else if(x==='csv')toast('Boekhoudexport blijft voor het tabblad Boekhouding.');});
function confirmPayment(ticket,amount,type,method){const r=repairs[ticket];if(!r){toast('Reparatie niet gevonden.');return}const open=due(r);if(!Number.isFinite(amount)||!(amount>0)){toast('Bedrag moet groter zijn dan 0.');return}if(amount>open+0.001){toast('Bedrag mag niet groter zijn dan open saldo.');return}const seq=1000+Object.values(repairs).reduce((s,x)=>s+x.payments.length,0)+1,ref='PAY-'+new Date().getFullYear()+'-'+String(seq).padStart(5,'0');const payment={id:uid('PAY'),ref,amount,method,type,at:now(),status:'confirmed'};r.payments.push(payment);log(r,type+' geregistreerd','',ref+' '+euro(amount)+' via '+method);try{save()}catch(e){r.payments.pop();r.audit.shift();toast('Opslaan mislukt. Betaling is niet geregistreerd.');return;}overlay('Betaling ontvangen ✓',`<div class="oc" style="text-align:center"><h1>${euro(amount)}</h1><p>${esc(ref)} · ${esc(method)}</p><p>Open saldo: ${euro(due(r))}</p><div class="toolbar" style="justify-content:center"><button class="btn s" data-action="repair-open-full" data-ticket="${esc(ticket)}">Terug naar dossier</button>${r.status==='Klaar'&&due(r)<=0?`<button class="btn g" data-action="pickup" data-ticket="${esc(ticket)}">Toestel afgehaald</button>`:''}</div></div>`);}
repairShell();save();
